#define MAX_STEPS 80.
#define MAX_DIST 40.
#define SURFACE_DIST .001
#define inf (MAX_DIST+0.0)

#define TIME_MULTIPLIER 1.5
#define ORB_RADIUS 0.55
#define Q(p) p *= r(round(atan(p.x, p.y) * 4.) / 4.)
#define r(a) mat2(cos(a + asin(vec4(0,1,-1,0))))
vec3 path(float z) {
    return vec3(
        sin(z*.0)*4.,
        sin(z*.0),
        iTime*TIME_MULTIPLIER+0.5
    );
}

vec3 lightPosition(vec3 p) {
    p-=path(p.z);
    return p-vec3(
        0.,
       0.,
        0.+7.
    );
}

// modified from the fractal function found here:
// https://www.shadertoy.com/view/4XdfW4
float fractal(vec3 p, out vec3 rgb, int iterations){

p.xy/=1.-p.y*7.5;

  for (int i = 0; i < iterations; i++) {
    float n = abs(p.x+p.y*p.z);
    Q(p.xy);
    p = abs(p)/clamp(n,0.05,.9)-1.95;


  }
  rgb=vec3(p.x*p.y);
  return length(rgb*.1);
}

float scene(vec3 p, out vec3 rgb) {
	vec3 tun = abs(p - path(p.z));
    float orb = length(lightPosition(p))-ORB_RADIUS;
    float hit = min(orb,min(3.-tun.x,2.-tun.y));
    if (orb == hit) {
        fractal(vec3(tun.xy,sin(p.z)),rgb,6);
        rgb *= vec3(.05,1.5,.05);
    } else {
        fractal(vec3(tun.xy,sin(p.z)),rgb,7);
    }
    return hit;
}

float raymarch(vec3 ro, vec3 rd, out vec3 rgb) {
  float dist = 0.0;
  for(float i = 0.; i < MAX_STEPS; i++) {
    vec3 p = ro + rd * dist;
    float step = scene(p, rgb);
    dist += step;
    if(dist > MAX_DIST || step < SURFACE_DIST) {
        break;
    }
  }
  return dist;
}

mat3 lookAt(vec3 origin, vec3 target, float roll) {
  vec3 rr = vec3(1., 1., 1.0);
  vec3 ww = normalize(target - origin);
  vec3 uu = normalize(cross(ww, rr));
  vec3 vv = normalize(cross(uu, ww));
  return mat3(uu, vv, ww);
}

vec3 normal(vec3 p) {
  vec2 e = vec2(.01, 0);
  vec3 rgb;

  vec3 n = scene(p,rgb) - vec3(
    scene(p-e.xyy,rgb),
    scene(p-e.yxy,rgb),
    scene(p-e.yyx,rgb));

  return normalize(n);
}

const float tmax = 20.0;

float hash(float n) {
	return fract(sin(n)*43758.5453);
}

vec3 hash(vec3 p){ 

    float n = sin(dot(p, vec3(7, 157, 113)));    
    return fract(vec3(2097152, 262144, 32768)*n); 
}

float noise(float g) {
	float p = floor(g);
	float f = fract(g);

	return mix(hash(p), hash(p + 1.0), f);
}

float voronoi(vec3 x) {
	vec3 p = floor(x);
	vec3 f = fract(x);

	vec2 res = vec2(8.0);

	for(int i = -1; i <= 1; i++)
	for(int j = -1; j <= 1; j++)
	for(int k = -1; k <= 1; k++) {
		vec3 g = vec3(float(i), float(j), float(k));
		vec3 r = g + hash(p + g) - f;

		float d = max(abs(r.x), max(abs(r.y), abs(r.z)));

		if(d < res.x) {
			res.y = res.x;
			res.x = d;
		} else if(d < res.y) {
			res.y = d;
		}
	}

	return res.y - res.x;
}

vec3 material(vec3 p) {
	float v = 0.0;
	float a = 0.7, f = 1.0;

	for(int i = 0; i < 4; i++) {
		float v1 = voronoi(p*f + 5.0);
		float v2 = 0.0;

		if(i > 0) {
			v2 = voronoi(p*f*0.1 + 50.0 + 0.15*iTime);

			float va = 0.0, vb = 0.0;
			va = 1.50 - smoothstep(0.0, 0.1, v1);
			vb = 1.0 - smoothstep(0.0, 0.08, v2);
			v += a*pow(va*(0.5 + vb), 4.0);
		}

		v1 = 1.0 - smoothstep(0.0, 0.3, v1);
		v2 =  a*noise(v1*5.5 + 1.1);

		v += v2;

		f *= 7.0;
		a *= 0.5;
	}

	return vec3(pow(v, 7.0), pow(v, 4.0), pow(v, 2.0))*3.0;
}

